EulerPacketSourceGeometry.Guards.geometryData.{u_1} {U : Type u_1} [NormedAddCommGroup U]
  [InnerProductSpace ℝ U] [CompleteSpace U] {D : EulerTransversePacketProvider.Data U} {τ : ℝ}
  {hτ : 0 < τ} {hτT : τ < D.T} {P : EulerPacketSourceGeometry.ParentFrame D τ}
  {H : EulerTransversePacketProvider.HistoryData (D.initial τ hτ ⋯)}
  (A : EulerPacketSourceGeometry.Guards hτ hτT P H) (Ω : Set EulerSmoothLimit.Space) (h0 : 0 ∈ Ω)
  (hΩ : ∀ x ∈ Ω, ‖x‖ ≤ A.radius) : EulerPacketMovingFrame.PhysicalGeometryData { x // x ∈ Ω }

EulerPacketSourceGeometry.Guards.source_velocity_initial_error.{u_1} {U : Type u_1}
  [NormedAddCommGroup U] [InnerProductSpace ℝ U] [CompleteSpace U]
  {D : EulerTransversePacketProvider.Data U} {τ : ℝ} {hτ : 0 < τ} {hτT : τ < D.T}
  {P : EulerPacketSourceGeometry.ParentFrame D τ}
  {H : EulerTransversePacketProvider.HistoryData (D.initial τ hτ ⋯)}
  (A : EulerPacketSourceGeometry.Guards hτ hτT P H) (x : EulerSmoothLimit.Space)
  (hx : ‖x‖ ≤ A.radius) :
  |EulerPacketMovingFrame.scaledVelocity P.m P.v (A.sourceVelocity x) τ P.a P.epsilon 0 1 - 1| +
      |EulerPacketMovingFrame.scaledVelocity P.m P.v (A.sourceVelocity x) τ P.a P.epsilon 0 0 +
          EulerPacketSourceGeometry.Guards.slope hτ hτT P H A| ≤
    P.totalError hτ hτT H A.CM A.CH A.radius

